package br.cofra.studio.rtmp;
import java.io.*;import java.util.*;
public final class Amf0 {
 public static byte[] encode(Object... values)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);for(Object v:values)write(d,v,0);return b.toByteArray();}
 public static Map<String,Object> object(Object... pairs){Map<String,Object> map=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)map.put((String)pairs[i],pairs[i+1]);return map;}
 private static void text(DataOutputStream d,String s)throws IOException{byte[] b=s.getBytes("UTF-8");if(b.length>65535)throw new IOException("String AMF longa");d.writeShort(b.length);d.write(b);}
 private static void write(DataOutputStream d,Object o,int depth)throws IOException{if(depth>12)throw new IOException("AMF profundo");if(o==null){d.writeByte(5);}else if(o instanceof String){d.writeByte(2);text(d,(String)o);}else if(o instanceof Number){d.writeByte(0);d.writeDouble(((Number)o).doubleValue());}else if(o instanceof Boolean){d.writeByte(1);d.writeByte((Boolean)o?1:0);}else if(o instanceof Map){d.writeByte(3);for(Map.Entry<?,?> e:((Map<?,?>)o).entrySet()){text(d,(String)e.getKey());write(d,e.getValue(),depth+1);}d.write(new byte[]{0,0,9});}else throw new IOException("Tipo AMF inválido");}
 public static List<Object> decode(byte[] bytes)throws IOException{DataInputStream d=new DataInputStream(new ByteArrayInputStream(bytes));List<Object> list=new ArrayList<>();while(d.available()>0&&list.size()<128)list.add(read(d,0));return list;}
 private static String text(DataInputStream d,int size)throws IOException{if(size<0||size>1048576)throw new IOException("String AMF inválida");byte[] b=new byte[size];d.readFully(b);return new String(b,"UTF-8");}
 private static Object read(DataInputStream d,int depth)throws IOException{if(depth>12)throw new IOException("AMF profundo");int t=d.readUnsignedByte();switch(t){case 0:return d.readDouble();case 1:return d.readUnsignedByte()!=0;case 2:return text(d,d.readUnsignedShort());case 5:case 6:return null;case 3:case 8:{if(t==8)d.readInt();Map<String,Object> m=new LinkedHashMap<>();while(m.size()<512){int n=d.readUnsignedShort();if(n==0){int marker=d.readUnsignedByte();if(marker==9)return m;throw new IOException("AMF inválido");}m.put(text(d,n),read(d,depth+1));}throw new IOException("Objeto AMF longo");}case 10:{int n=d.readInt();if(n<0||n>512)throw new IOException("Lista AMF longa");List<Object> a=new ArrayList<>();for(int i=0;i<n;i++)a.add(read(d,depth+1));return a;}case 11:{double v=d.readDouble();d.readShort();return v;}case 12:return text(d,d.readInt());default:throw new IOException("Tipo AMF não suportado");}}
}
